  try{ body = F.tab === "pr" ? vPr() : F.tab === "fa" ? vFa() : F.tab === "pl" ? vPl() : F.tab === "qa" ? vQa() : F.tab === "sp" ? vSp() : F.tab === "or" ? vOr() : F.tab === "ac" ? vAc() : F.tab === "up" ? vUp() : vOv(); }catch(e){ console.error(e); body = '<div class="c emp">Could not draw this page: ' + esc(e.message || e) + '</div>'; }
